def transform(grid):
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for i, row in enumerate(grid):
        colored = [j for j, v in enumerate(row) if v != bg]
        if colored and colored[0] > 0 and colored[-1] < len(row)-1:
            for j in range(colored[-1]+1, len(row)):
                out[i][j] = 1
    return out
